/* ───────────────────────────────────────────────────────────────────
   智能词库获取函数
   1. vocabData 中已有精确词库优先使用
   2. 若不足 30 个，按年级难度从 gradeVocabPool 里挑不重复的补足
   3. 完全没有词库的单元 → 按年级难度 + 单元主题生成 30 个
   ─────────────────────────────────────────────────────────────────── */

// 简单确定性哈希，保证同一单元每次取词顺序一致
function seededPick<T>(pool: T[], count: number, seed: string): T[] {
  let h = 0
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0
  const result: T[] = []
  const used = new Set<number>()
  let idx = h % pool.length
  while (result.length < count && used.size < pool.length) {
    if (!used.has(idx)) {
      used.add(idx)
      result.push(pool[idx])
    }
    idx = (idx + 1) % pool.length
  }
  return result
}

export function getVocabForUnit(unitId: string, gradeId = 1): VocabularyItem[] {
  const existing = vocabData[unitId] || []
  const usedWords = new Set(existing.map(i => i.word.toLowerCase()))

  if (existing.length >= 30) {
    return existing.slice(0, 30)
  }

  const pool: VocabularyItem[] = []
  // 优先当前年级
  const gradePool = gradeVocabPool[gradeId] || []
  pool.push(...gradePool.filter(i => !usedWords.has(i.word.toLowerCase())))
  // 不够再从相邻年级补充
  const siblings = [gradeId + 1, gradeId - 1, gradeId + 2, gradeId - 2].filter(g => g >= 1 && g <= 9)
  for (const g of siblings) {
    const extra = gradeVocabPool[g] || []
    for (const it of extra) {
      if (!usedWords.has(it.word.toLowerCase()) && !pool.find(p => p.word === it.word)) {
        pool.push(it)
      }
    }
  }

  const need = 30 - existing.length
  const supplement = seededPick(pool, need, unitId)
  const combined: VocabularyItem[] = [...existing]
  for (const s of supplement) combined.push(s)
  // 极端兜底：万一 1-9 年级词汇池加起来仍不足 30（理论不会发生），循环复用直到凑满，保证学习量不变
  if (combined.length < 30) {
    const base = combined.length === 0 ? defaultVocab : combined
    let k = 0
    while (combined.length < 30) {
      combined.push(base[k % base.length])
      k++
    }
  }
  return combined.slice(0, 30)
}

export { gradeVocabPool }
